#!/usr/bin/env bash
unity command --project-path . eval 'var c = typeof(MechaCyberpunk.Core.CandadosMundo); return MechaCyberpunk.Progresion.Recorrido.DirectorRecorrido.DepurarHistoria() + " | pol=" + MechaCyberpunk.Core.CandadosMundo.Policia + " pand=" + MechaCyberpunk.Core.CandadosMundo.Pandillas + " nova=" + MechaCyberpunk.Core.CandadosMundo.Nova + " robo=" + MechaCyberpunk.Core.CandadosMundo.RoboCarros + " tiendas=" + MechaCyberpunk.Core.CandadosMundo.Tiendas + "/" + MechaCyberpunk.Core.CandadosMundo.TiendaAbierta + " mision=" + MechaCyberpunk.Core.MisionProtegida.Activa;' --result-only 2>&1 | tail -3
